files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #565758;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #001a33;
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;

  --font-family: 'Open Sans', sans-serif;
  --h1-font-size: 48px;
  --h2-font-size: 36px;
  --h3-font-size: 32px;
  --h4-font-size: 28px;
  --h5-font-size: 24px;
  --h6-font-size: 22px;
  --p-font-size: 18px;
  --menu-font-size: 16px;
  --font-weight-light: 300;
  --font-weight-normal: 400;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  font-family: var(--font-family);
  color: var(--vt-ink);
  background: var(--vt-surface);
  position: relative;
  padding-top: 94px;
  min-height: 100vh;
  overflow-x: hidden;
}

.root a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: color 0.3s;
}

.root a:hover {
  color: var(--vt-accent);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* Typography */
.root h1, .root h2, .root h3, .root h4, .root h5, .root h6 {
  color: var(--vt-ink);
  font-weight: var(--font-weight-semibold);
  line-height: 1.2;
}

.root h1, .root h2 {
  font-weight: var(--font-weight-bold);
}

.root h1 { font-size: var(--h1-font-size); }
.root h2 { font-size: var(--h2-font-size); }
.root h3 { font-size: var(--h3-font-size); }
.root h4 { font-size: var(--h4-font-size); }
.root h5 { font-size: var(--h5-font-size); }
.root h6 { font-size: var(--h6-font-size); }

.root p {
  color: var(--vt-ink-soft);
  font-size: var(--p-font-size);
  font-weight: var(--font-weight-light);
  letter-spacing: 0.5px;
  line-height: 1.6;
}

/* Container */
.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
  width: 100%;
  box-sizing: border-box;
}

.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

/* Navigation */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  background: var(--vt-surface);
  box-shadow: 0 0 20px rgba(0, 0, 0, 0.1);
  z-index: 1000;
  padding: 20px 0;
}

.navIn {
  display: flex;
  justify-content: space-between;
  align-items: center;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.logo {
  display: inline-block;
}

.brand {
  display: block;
  color: var(--vt-accent);
  font-size: var(--h5-font-size);
  font-weight: var(--font-weight-bold);
  text-align: center;
}

.brand strong {
  display: block;
  color: var(--vt-ink-soft);
  font-size: 12px;
  font-weight: var(--font-weight-normal);
  margin-top: -5px;
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  font-weight: var(--font-weight-semibold);
  font-size: var(--menu-font-size);
  padding: 5px 0;
}

.navLinks a:hover {
  color: var(--vt-ink);
}

/* Hero */
.hero {
  padding-top: 0;
}

.heroContainer {
  position: relative;
  overflow: hidden;
  height: 580px;
}

.heroSlider {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 100%;
  -webkit-overflow-scrolling: touch;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  height: 100%;
}

.heroImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  background: var(--vt-surface);
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  padding: 1.5rem 2.5rem;
  width: 50%;
  box-sizing: border-box;
}

.heroTitle {
  margin-top: 0;
  margin-bottom: 0.5rem;
  font-size: var(--h1-font-size);
  color: var(--vt-ink);
}

.heroDesc {
  margin-bottom: 1.5rem;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
}

.customLink {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: var(--font-weight-semibold);
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
  transition: color 0.3s;
}

.customLink::before {
  content: attr(data-hover);
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--vt-line);
  color: var(--vt-accent);
  line-height: 40px;
  text-align: center;
  transition: top 0.3s cubic-bezier(0.19, 1, 0.56, 1);
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  margin: 0;
  font-weight: var(--font-weight-semibold);
  color: var(--vt-ink-soft);
}

/* About */
.aboutRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 40px;
}

.aboutColText {
  flex: 1 1 55%;
}

.aboutColImage {
  flex: 1 1 35%;
  display: flex;
  justify-content: center;
}

.aboutTitle {
  margin-bottom: 1rem;
}

.aboutImage {
  width: 350px;
  height: 350px;
  object-fit: cover;
  border-radius: 50%;
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

/* Gallery */
.gallery {
  padding: 0;
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
}

.galleryCol {
  flex: 1 1 50%;
  padding: 0;
}

.galleryImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* Timeline */
.timelineSection {
  padding-bottom: 0;
}

.timelineTitle {
  text-align: center;
  margin-bottom: 3rem;
}

.timeline {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  transform: translateX(-50%);
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 1;
}

.timelineNode {
  display: flex;
  align-items: flex-start;
  position: relative;
  margin-bottom: 2.5rem;
}

.timelineDate {
  flex: 0 0 120px;
  padding: 1.5rem 0;
  text-align: right;
  color: var(--vt-ink-soft);
  font-size: var(--menu-font-size);
  font-weight: var(--font-weight-semibold);
}

.timelineIconWrap {
  flex: 0 0 80px;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  z-index: 10;
  margin: 0 20px;
}

.timelineIconWrap::before {
  content: "";
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  z-index: 1;
}

.timelineIcon {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: var(--h3-font-size);
  position: relative;
  z-index: 2;
}

.timelineIcon::after {
  content: "✓";
  color: var(--vt-on-accent);
  font-size: 24px;
}

.timelineContent {
  flex: 1;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  border-radius: 4px;
  padding: 0;
  position: relative;
}

.timelineHeading {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  margin: 0;
  padding: 10px 30px;
  border-radius: 4px 4px 0 0;
  font-size: var(--h5-font-size);
  position: relative;
}

.timelineText {
  padding: 10px 30px;
  margin: 0;
}

/* Alternating timeline layout */
.timelineNode:nth-child(odd) .timelineDate {
  order: 1;
  text-align: left;
}

.timelineNode:nth-child(odd) .timelineIconWrap {
  order: 2;
}

.timelineNode:nth-child(odd) .timelineContent {
  order: 3;
}

.timelineNode:nth-child(odd) .timelineHeading::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  width: 0;
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode:nth-child(even) .timelineDate {
  order: 3;
  text-align: right;
}

.timelineNode:nth-child(even) .timelineIconWrap {
  order: 2;
}

.timelineNode:nth-child(even) .timelineContent {
  order: 1;
}

.timelineNode:nth-child(even) .timelineHeading::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  width: 0;
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

/* Mobile timeline */
@media (max-width: 767px) {
  .timeline::before {
    left: 33px;
    top: 60px;
    height: 90%;
  }

  .timelineNode {
    flex-direction: column;
    padding-left: 80px;
    margin-bottom: 2rem;
  }

  .timelineNode:nth-child(odd) .timelineDate,
  .timelineNode:nth-child(even) .timelineDate {
    order: 1;
    text-align: left;
    padding: 0;
  }

  .timelineNode:nth-child(odd) .timelineIconWrap,
  .timelineNode:nth-child(even) .timelineIconWrap {
    order: 0;
    position: absolute;
    left: 0;
    top: 0;
    margin: 0;
  }

  .timelineNode:nth-child(odd) .timelineContent,
  .timelineNode:nth-child(even) .timelineContent {
    order: 2;
    width: 100%;
  }

  .timelineNode:nth-child(odd) .timelineHeading::after,
  .timelineNode:nth-child(even) .timelineHeading::after {
    left: auto;
    right: 100%;
    border-left: 0;
    border-right: 10px solid var(--vt-surface-deep);
  }

  .timelineIconWrap::before {
    width: 75px;
    height: 75px;
  }

  .timelineIcon {
    width: 75px;
    height: 75px;
  }

  .timelineIcon::after {
    font-size: 20px;
  }
}

@media (max-width: 575px) {
  .timeline::before {
    left: 57px;
  }

  .timelineIconWrap::before {
    width: 70px;
    height: 70px;
  }

  .timelineIcon {
    width: 70px;
    height: 70px;
  }
}

/* Contact */
.contactSection {
  padding-top: 5rem;
}

.contactTitle {
  text-align: center;
  margin-bottom: 3rem;
}

.contactWrap {
  max-width: 100%;
  overflow: hidden;
}

.socialLinks {
  text-align: center;
  margin-top: 2rem;
}

/* Footer */
.footer {
  background: var(--vt-surface-2);
  padding: 5rem 0;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 30px;
  align-items: flex-start;
}

.footerCol {
  flex: 1 1 200px;
  min-width: 0;
  box-sizing: border-box;
}

.footerColCopyright {
  width: 100%;
}

.footerHeading {
  color: var(--vt-ink);
  margin-bottom: 1.5rem;
}

.footerText,
.hoursText {
  color: var(--vt-ink-soft);
  font-size: var(--p-font-size);
  line-height: 1.6;
  white-space: pre-line;
}

.copyrightText {
  font-size: var(--menu-font-size);
  color: var(--vt-ink-soft);
  text-align: center;
  margin-top: 2rem;
}

/* Responsive overrides */
@media screen and (min-width: 1600px) {
  .heroContainer {
    height: 740px;
  }
}

@media screen and (max-width: 991px) {
  .root {
    padding-top: 74px;
  }

  .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }

  .nav {
    padding-top: 10px;
    padding-bottom: 10px;
  }

  .heroContainer {
    height: auto;
  }

  .heroText {
    position: relative;
    bottom: 100px;
    left: 0;
    width: auto;
    margin-bottom: -100px;
    padding: 2rem;
  }

  .aboutImage {
    width: 320px;
    height: 320px;
  }
}

@media screen and (max-width: 767px) {
  .heroText {
    padding: 1.5rem;
  }

  .aboutImage {
    width: 250px;
    height: 250px;
  }
}

@media screen and (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }

  .heroLinks .customLink {
    font-size: 12px;
    line-height: 30px;
    padding: 0 25px;
  }

  .contactPhone {
    font-size: 12px;
  }
}

@media screen and (max-width: 360px) {
  .aboutImage {
    width: 235px;
    height: 235px;
  }
}
